import{d as s,C as n,o as d,c as p,E as i,a3 as r}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"谦卦","description":"第十五卦·地山谦——天道亏盈而益谦，地中有山","frontmatter":{"title":"谦卦","description":"第十五卦·地山谦——天道亏盈而益谦，地中有山","category":"hexagram","aliases":["谦","地山谦"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/15-dishanqian.md","filePath":"yijing/hexagrams/15-dishanqian.md","lastUpdated":1792641266000}'),h={name:"yijing/hexagrams/15-dishanqian.md"},y=s({...h,setup(m){const e=[{id:"qian",term:"谦",pinyin:"qiān",meaning:"谦逊、谦德。上坤下艮，山藏于地下——有山之实而不露。",context:"谦不是孤立的性格特质，而是「艮之实」与「坤之地」两个条件同时成立的结构。"},{id:"youzhong",term:"君子有终",pinyin:"jūn zǐ yǒu zhōng",meaning:"君子能有善终。有终：有好的结局。",context:"谦卦是六十四卦中唯一六爻皆吉的卦，其判词落在「有终」上。"},{id:"qianqian",term:"谦谦君子",pinyin:"qiān qiān jūn zǐ",meaning:"谦而又谦的君子。",context:"初六居全卦最低最初之处，故曰「谦谦」。"},{id:"beiyizimu",term:"卑以自牧",pinyin:"bēi yǐ zì mù",meaning:"以谦卑修养自身。牧：养。"},{id:"sheyoudachuan",term:"用涉大川",pinyin:"yòng shè dà chuān",meaning:"用以渡涉大川。涉：渡。",context:"不是「因为谦所以能渡」的交换，而是谦本身就是渡险的方法。"},{id:"mingqian",term:"鸣谦",pinyin:"míng qiān",meaning:"有声名的谦、显于外的谦。鸣：发声、显露。",context:"六二「鸣谦」与上六「鸣谦」同辞而不同境，一见「中心得」，一见「志未得」。"},{id:"zhongxinde",term:"中心得也",pinyin:"zhōng xīn dé yě",meaning:"发自内心而有所得。中心：内心。",context:"六二象曰：「鸣谦贞吉，中心得也。」"},{id:"laoqian",term:"劳谦",pinyin:"láo qiān",meaning:"有功劳而仍谦。劳：功劳、劳绩。",context:"九三为全卦唯一阳爻，得位、得正、有应——谦的前提是有实绩。"},{id:"wanminfu",term:"万民服也",pinyin:"wàn mín fú yě",meaning:"万民悦服。九三象曰，释「有终吉」。"},{id:"huiqian",term:"㧑谦",pinyin:"huī qiān",meaning:"㧑：通「撝」，挥、施展。主动地、向外地施展谦德。",context:"六四。不同于六二的自然流露，是主动引发共鸣的谦——但有边界，故曰「不违则」。"},{id:"buweize",term:"不违则",pinyin:"bù wéi zé",meaning:"不违背法则、不逾越本分。则：法则、分寸。"},{id:"bufu",term:"不富以其邻",pinyin:"bù fù yǐ qí lín",meaning:"不靠财货而能与邻共。不富：不靠富有（笼络）；以其邻：与邻同。",context:"同泰卦六四语。谦德自然感召同质之邻，不必用财。"},{id:"qinfa",term:"利用侵伐",pinyin:"lì yòng qīn fá",meaning:"宜于用征伐。",context:"不是扩张野心，是对始终不肯归顺者的最后匡正——谦有底线。"},{id:"zhengbufu",term:"征不服",pinyin:"zhēng bù fú",meaning:"征讨不肯归服者。六五象曰。"},{id:"zhengweide",term:"志未得也",pinyin:"zhì wèi dé yě",meaning:"心愿尚未达成。上六象曰。",context:"同样「鸣谦」，六二是「中心得」，上六却是「志未得」——有德而无位。"},{id:"yiguo",term:"征邑国",pinyin:"zhēng yì guó",meaning:"征治自己的邑国。邑国：自身封地。",context:"非对外征伐，与六五「征不服」性质不同——只能自守本分的收尾状态。"},{id:"poudou",term:"裒多益寡",pinyin:"póu duō yì guǎ",meaning:"取多补少。裒：取、聚。象传语。",context:"谦不是低调做人，而是资源再分配的动态过程。"},{id:"chengwupingshi",term:"称物平施",pinyin:"chèng wù píng shī",meaning:"称：读 chèng，衡量。衡量事物而公平施与。"},{id:"xiakji",term:"天道下济",pinyin:"tiān dào xià jì",meaning:"天道向下济助。济：施与。",context:"彖传：「天道下济而光明，地道卑而上行。」高者下行、卑者上应，成双向往还。"},{id:"bukeyu",term:"卑而不可逾",pinyin:"bēi ér bù kě yú",meaning:"处卑而不可逾越。逾：越过。",context:"谦始终是「有分寸的低」，不是没有边界的无限退让。"}],o=[{position:"初六",type:"yin",text:"谦谦君子，用涉大川，吉。",xiang:"谦谦君子，卑以自牧也。",textModern:"谦而又谦的君子，凭此渡涉大川，吉。",xiangModern:"谦谦君子，是以谦卑修养自身——谦不是配重物，它本身就是渡险之法。"},{position:"六二",type:"yin",text:"鸣谦，贞吉。",xiang:"鸣谦贞吉，中心得也。",textModern:"有声名而仍谦，守正则吉。",xiangModern:"鸣谦之所以贞吉，是因为发自内心而有所得——不是表演给人看。"},{position:"九三",type:"yang",text:"劳谦君子，有终吉。",xiang:"劳谦君子，万民服也。",textModern:"有功劳而仍谦的君子，能有善终，吉。",xiangModern:"劳谦君子，万民悦服——「有终」是「万民服」这个更大格局下的自然产物。"},{position:"六四",type:"yin",text:"无不利，㧑谦。",xiang:"无不利㧑谦，不违则也。",textModern:"无所不利，主动施展谦德。",xiangModern:"施展谦德而无所不利，因为不逾越分寸——可以感召他人，绝不僭越抢功。"},{position:"六五",type:"yin",text:"不富以其邻，利用侵伐，无不利。",xiang:"利用侵伐，征不服也。",textModern:"不靠财货而与邻共，宜于用征伐，无所不利。",xiangModern:"用征伐，是为了匡正始终不肯归服者——谦有底线，不是无限退让。"},{position:"上六",type:"yin",text:"鸣谦，利用行师，征邑国。",xiang:"鸣谦，志未得也。可用行师，征邑国也。",textModern:"同样显扬谦德，宜于用兵，征治自己的邑国。",xiangModern:"鸣谦而「志未得」，是心愿始终未能达成——有德而无位，只能自守本分。"}];return(u,t)=>{const a=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),g=n("DaoKeywordCards");return d(),p("div",null,[i(a,{name:"谦",fullName:"地山谦",upper:"☷",lower:"☶",guaCi:"谦，亨，君子有终。",pinyin:["qiān"],element:"金",direction:"西",virtue:"谦",insight:"山藏于地下，有实而不露；谦有二质——艮之实，坤之地。",guaSlug:"15dishanqian",lines:o}),t[0]||(t[0]=r('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>地中有山，谦。君子以裒多益寡，称物平施。</p><p>地中有山：山本高耸，如今藏在土里——<strong>有山之实，却无山之势</strong>，这是谦之象。大象给出的不是一句品行劝告，而是一条操作指令：</p><ul><li><strong>裒多益寡</strong> —— 裒（póu）是取、聚。取多的，补少的。</li><li><strong>称物平施</strong> —— 称（chèng）是衡量。衡量事物，公平施与。</li></ul><p>所以「谦」不是低调做人，而是<strong>资源再分配的动态过程</strong>，如同天平寻找平衡。山之所以要藏在地中，不是为了自我压抑，而是因为它本来就在做这件事：把高处的东西往下送。</p><p>分形结构：</p><ul><li>山（艮）→ 实而止：有实质、有边界、有止息的定力</li><li>地（坤）→ 顺而受：有容量、有承载，能接住这份实</li></ul><p><strong>一有实，一能载，谦才立得住。</strong></p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>谦亨。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。</p><p>逐句释义：</p><ul><li><strong>天道下济而光明，地道卑而上行</strong> —— 天道向下济助而光明，地道处在卑位而向上回应。高者下行、卑者上应，形成<strong>双向往还的动态平衡</strong>——这是谦之所以亨通的机理。</li><li><strong>天道亏盈而益谦</strong> —— 天之道，减损满盈的，增益谦下的。</li><li><strong>地道变盈而流谦</strong> —— 地之道，改变满盈的，流向谦下的。</li><li><strong>鬼神害盈而福谦</strong> —— 鬼神祸害满盈的，福佑谦下的。</li><li><strong>人道恶盈而好谦</strong> —— 人之道，讨厌满盈的，喜爱谦下的。天、地、鬼神、人四层同向，这是全卦的底气所在。</li><li><strong>谦尊而光</strong> —— 有实绩（尊）却不显露（光）。<strong>对应九三</strong>：全卦唯一阳爻，是全卦的骨架与力量支撑。</li><li><strong>卑而不可逾</strong> —— 处低位而守正，不越界。<strong>对应六二</strong>：发自内心的谦，故不可逾。</li><li><strong>君子之终也</strong> —— 这正是君子的归宿（与卦辞「君子有终」呼应）。</li></ul><blockquote><p><strong>一处天道逻辑的校正</strong>：《道德经》与《易经》在此是一致的——<strong>「天道损有余而补不足」</strong>，这是宇宙的自我调节机制，而不是「损不足以奉有余」。谦之所以无往不利，是因为它站在这条机制的同侧。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',14)),i(l,{element:"金",guaSlug:"15dishanqian",glossary:e,items:o}),t[1]||(t[1]=r('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-谦谦君子-用涉大川-吉" tabindex="-1">初六 · 谦谦君子，用涉大川，吉 <a class="header-anchor" href="#初六-·-谦谦君子-用涉大川-吉" aria-label="Permalink to &quot;初六 · 谦谦君子，用涉大川，吉&quot;">​</a></h3><ul><li><strong>谦谦</strong> → 谦而又谦</li><li><strong>用涉大川</strong> → 凭此渡涉大川</li><li><strong>卑以自牧</strong> → 以谦卑修养自身（牧：养）</li></ul><p>初六居全卦最低、最初、力量最弱之处，故曰「谦谦」。此爻最要紧的一层辨析是：<strong>谦不是用来对抗危险的「配重物」，谦本身就是穿越危险的方法</strong>。</p><p>处境（大川）与态度（谦谦）之间是<strong>因果关系</strong>，不是同一量纲下可以放在天平两端对比的东西。</p><blockquote><p>水之喻：水是最谦的东西，毫无棱角要维护，正因如此，才能穿越任何险境而不被摧毁。</p></blockquote><h3 id="六二-·-鸣谦-贞吉" tabindex="-1">六二 · 鸣谦，贞吉 <a class="header-anchor" href="#六二-·-鸣谦-贞吉" aria-label="Permalink to &quot;六二 · 鸣谦，贞吉&quot;">​</a></h3><ul><li><strong>鸣谦</strong> → 有声名而仍谦</li><li><strong>贞吉</strong> → 守正则吉</li><li><strong>中心得也</strong> → 发自内心而有所得</li></ul><p>谦是<strong>含蓄而不彰显的表达</strong>——露而不锋，光而不耀。这份谦逊之所以站得住，是因为它是从内心真正安顿、真正有所得之后自然流露的，不是刻意演给别人看的。</p><p>象曰「鸣谦贞吉，中心得也」——「中心得」三字是六二的分量所在。</p><blockquote><p>核心洞见：能鸣，是因为内有得。内无所得而鸣，那就只是叫。</p></blockquote><h3 id="九三-·-劳谦君子-有终吉" tabindex="-1">九三 · 劳谦君子，有终吉 <a class="header-anchor" href="#九三-·-劳谦君子-有终吉" aria-label="Permalink to &quot;九三 · 劳谦君子，有终吉&quot;">​</a></h3><ul><li><strong>劳谦</strong> → 有功劳而仍谦</li><li><strong>有终吉</strong> → 能有善终</li><li><strong>万民服也</strong> → 万民悦服</li></ul><p>结构上，九三为全卦<strong>唯一阳爻</strong>，得位、得正、有应——这正是彖传「谦尊而光」所指的那一处：全卦的骨架与力量支撑。</p><p>核心洞见在于：<strong>谦的前提是有功劳、有实绩佑身</strong>。无功而谦，反而容易被看作虚伪、做作。所以这一爻的「有终吉」，不是苟且偷生的结果，而是**「万民服」这个更大格局下的自然产物**。</p><blockquote><p>核心洞见：有实，才谈得上藏实；无实之藏，是空。</p></blockquote><h3 id="六四-·-无不利-㧑谦" tabindex="-1">六四 · 无不利，㧑谦 <a class="header-anchor" href="#六四-·-无不利-㧑谦" aria-label="Permalink to &quot;六四 · 无不利，㧑谦&quot;">​</a></h3><ul><li><strong>㧑（huī）谦</strong> → 主动向外施展谦德（㧑通「撝」，挥、施展）</li><li><strong>不违则</strong> → 不违背法则、不逾越本分</li></ul><p>位置上，六四上邻六五（君位）、下邻九三（劳谦重臣），是承上启下的臣位。</p><p>与六二的分辨很清楚：「㧑」是<strong>主动地、向外地施展谦德</strong>，不同于六二的「鸣」那种自然流露。它是「把德行引起别人共鸣」的谦——但<strong>有边界</strong>：「不违则」——可以主动施展、感召他人，绝不能僭越、不能抢功。</p><blockquote><p>核心洞见：谦可以主动，但主动不等于越位。这一爻把「分寸」两个字写在了最显眼处。</p></blockquote><h3 id="六五-·-不富以其邻-利用侵伐-无不利" tabindex="-1">六五 · 不富以其邻，利用侵伐，无不利 <a class="header-anchor" href="#六五-·-不富以其邻-利用侵伐-无不利" aria-label="Permalink to &quot;六五 · 不富以其邻，利用侵伐，无不利&quot;">​</a></h3><ul><li><strong>不富以其邻</strong> → 不靠财货而能与邻共</li><li><strong>利用侵伐</strong> → 宜于用征伐</li><li><strong>征不服也</strong> → 为征讨不肯归服者</li></ul><p>结构上，六五阴爻居阳位<strong>不得位</strong>；与六二同为阴爻、<strong>不能相应</strong>——是全卦唯一「失位又失应」的一爻。</p><ul><li><strong>「不富，以其邻」</strong>（同泰卦六四语）：不靠财货笼络人心，靠谦德自然感召同质之邻爻（六四、上六）。</li><li><strong>「利用侵伐」</strong>：并非扩张野心，而是对始终不肯归顺的顽固者<strong>最后的匡正手段</strong>。象曰「征不服也」。</li></ul><p>这一爻揭示了谦的另一面：<strong>外柔内刚</strong>——谦有底线，不是无限退让。</p><blockquote><p>核心洞见：真正的谦者是柔的，但那份柔里有骨头。</p></blockquote><h3 id="上六-·-鸣谦-利用行师-征邑国" tabindex="-1">上六 · 鸣谦，利用行师，征邑国 <a class="header-anchor" href="#上六-·-鸣谦-利用行师-征邑国" aria-label="Permalink to &quot;上六 · 鸣谦，利用行师，征邑国&quot;">​</a></h3><ul><li><strong>鸣谦</strong> → 同样显扬谦德（与六二同辞）</li><li><strong>志未得也</strong> → 心愿始终未能达成</li><li><strong>征邑国</strong> → 征治自己的邑国</li></ul><p>位置上，上六在君位之上，已超出权力中心——如退居幕后的元老、心系天下的长者。</p><p>与六二的对照是全卦最见分寸的一处：</p><table tabindex="0"><thead><tr><th></th><th>鸣谦</th><th>结果</th></tr></thead><tbody><tr><td>六二</td><td>发自内心流露</td><td><strong>中心得也</strong>（内心已安顿、已有得）</td></tr><tr><td>上六</td><td>同样表达谦德</td><td><strong>志未得也</strong>（心愿始终未能达成）</td></tr></tbody></table><p>同一句「鸣谦」，两处心境不同。核心洞见是<strong>有德而无位</strong>——话是对的、心是好的，却缺少施展的舞台。</p><p>「邑国」须辨明：仅指上六自身封地范围内的城邑，<strong>非对外征伐</strong>，与六五「征不服」性质不同——这是无力扩张、只能自守本分的收尾状态。</p><blockquote><p>核心洞见：志未得，却仍守本分、行师以治其邑。这是谦卦的最后一个姿势。</p></blockquote><h2 id="谦之二质-艮之实-与-坤之地" tabindex="-1">谦之二质：艮之实 与 坤之地 <a class="header-anchor" href="#谦之二质-艮之实-与-坤之地" aria-label="Permalink to &quot;谦之二质：艮之实 与 坤之地&quot;">​</a></h2><p>谦并非孤立的性格特质，而是<strong>两个条件同时成立的结构</strong>：</p><ol><li><strong>艮之实</strong>：具备山的实质、边界与止息的定力</li><li><strong>坤之地</strong>：找对能承载的场域——地之容量，决定了谦与失衡的界限</li></ol><blockquote><p><strong>若无实则为虚伪，若无地则为埋没。</strong></p></blockquote><p>这一层框架能解释很多困惑：为什么有人低调却令人敬重，有人低调却毫无声响？差别不在「低」的程度，而在<strong>有没有实、有没有地</strong>。</p><h2 id="天道调节-亏盈益谦-与-称物平施" tabindex="-1">天道调节：亏盈益谦 与 称物平施 <a class="header-anchor" href="#天道调节-亏盈益谦-与-称物平施" aria-label="Permalink to &quot;天道调节：亏盈益谦 与 称物平施&quot;">​</a></h2><p>谦的底层是一条自然的调节机制，可以借两个模型看清：</p><p><strong>气味扩散</strong>：浓度高向低处自然流动，无需外力干预。这是「亏盈益谦」最朴素的形态。</p><p><strong>墨汁稀释（墨滴模型）</strong>：同样的「山」（墨滴），在不同的「地」里结果截然不同——</p><table tabindex="0"><thead><tr><th>落处</th><th>结果</th></tr></thead><tbody><tr><td>一杯清水</td><td>全黑</td></tr><tr><td>一海之水</td><td>无痕</td></tr></tbody></table><p>同一滴墨，因为<strong>地</strong>不同，一个是全部、一个是虚无。这正印证了「找对地」的重要——它与「谦之二质」中的「坤之地」，是同一判断的两种表达。</p><p>而落到人的行动上，就是象传那八个字：<strong>裒多益寡，称物平施</strong>——像天平寻找平衡。谦因此从来不是姿态问题，而是分配问题。</p><h2 id="附辨-谦-与-「潜龙勿用」的分野" tabindex="-1">附辨：谦 与 「潜龙勿用」的分野 <a class="header-anchor" href="#附辨-谦-与-「潜龙勿用」的分野" aria-label="Permalink to &quot;附辨：谦 与 「潜龙勿用」的分野&quot;">​</a></h2><p>两者表面都是「藏」，性质完全不同：</p><table tabindex="0"><thead><tr><th></th><th>性质</th><th>原因</th></tr></thead><tbody><tr><td>乾初九（潜龙勿用）</td><td>被动的、等待时机的隐</td><td>因时未到</td></tr><tr><td>地山谦</td><td>主动的、关系性的隐</td><td>因实已具，故选择蛰伏</td></tr></tbody></table><p>一个是<strong>还没到时候所以不动</strong>，一个是<strong>已经具备却选择不动</strong>。前者是时势所限，后者是主体选择——这正是谦之所以为「德」而非「处境」的原因。</p><h2 id="藏-·-鸣-·-㧑-——-谦的表达次第" tabindex="-1">藏 · 鸣 · 㧑 —— 谦的表达次第 <a class="header-anchor" href="#藏-·-鸣-·-㧑-——-谦的表达次第" aria-label="Permalink to &quot;藏 · 鸣 · 㧑 —— 谦的表达次第&quot;">​</a></h2><p>全卦对「谦如何表达」给了三种形态，恰好是三个位置：</p><ul><li><strong>六二（鸣）</strong>：自然流露。不鸣则藏。</li><li><strong>九三（劳）</strong>：有实绩方可谦，否则显虚伪——这是谦的<strong>地基</strong>。</li><li><strong>六四（㧑）</strong>：主动施展，引发共鸣，但不逾矩。</li></ul><p>同一条底线，在不同位置换了不同的名字反复出现：</p><table tabindex="0"><thead><tr><th>出处</th><th>表述</th></tr></thead><tbody><tr><td>彖传</td><td><strong>卑而不逾</strong></td></tr><tr><td>六二</td><td><strong>贞</strong>（守正）</td></tr><tr><td>六四</td><td><strong>不违则</strong></td></tr></tbody></table><blockquote><p>谦，始终是「有分寸的低」，不是没有边界的无限退让。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',58)),i(g,{title:"字词释义",items:[{term:"谦",pinyin:["qiān"],meaning:"谦逊、谦德。山藏于地下，有实而不露。"},{term:"有终",pinyin:["yǒu","zhōng"],meaning:"有善终、有好的结局。卦辞「君子有终」。"},{term:"谦谦",pinyin:["qiān","qiān"],meaning:"谦而又谦。初六居全卦最低最初之处。"},{term:"卑以自牧",pinyin:["bēi","yǐ","zì","mù"],meaning:"以谦卑修养自身。牧：养。"},{term:"涉大川",pinyin:["shè","dà","chuān"],meaning:"渡涉大川。涉：渡。"},{term:"鸣谦",pinyin:["míng","qiān"],meaning:"显于外的谦。鸣：发声、显露。"},{term:"中心得也",pinyin:["zhōng","xīn","dé","yě"],meaning:"发自内心而有所得。中心：内心。"},{term:"劳谦",pinyin:["láo","qiān"],meaning:"有功劳而仍谦。劳：功劳。"},{term:"万民服也",pinyin:["wàn","mín","fú","yě"],meaning:"万民悦服。"},{term:"㧑谦",pinyin:["huī","qiān"],meaning:"㧑通「撝」，挥、施展。主动向外施展谦德。"},{term:"不违则",pinyin:["bù","wéi","zé"],meaning:"不违背法则、不逾越本分。则：分寸。"},{term:"不富以其邻",pinyin:["bù","fù","yǐ","qí","lín"],meaning:"不靠财货而能与邻共。"},{term:"利用侵伐",pinyin:["lì","yòng","qīn","fá"],meaning:"宜于用征伐。非扩张，是匡正不服者。"},{term:"征不服",pinyin:["zhēng","bù","fú"],meaning:"征讨不肯归服者。"},{term:"志未得也",pinyin:["zhì","wèi","dé","yě"],meaning:"心愿尚未达成。"},{term:"征邑国",pinyin:["zhēng","yì","guó"],meaning:"征治自身封地的城邑。邑国：封地。"},{term:"裒多益寡",pinyin:["póu","duō","yì","guǎ"],meaning:"取多补少。裒：取、聚。"},{term:"称物平施",pinyin:["chèng","wù","píng","shī"],meaning:"称：读 chèng，衡量。衡量事物而公平施与。"},{term:"天道下济",pinyin:["tiān","dào","xià","jì"],meaning:"天道向下济助。济：施与。"},{term:"卑而不可逾",pinyin:["bēi","ér","bù","kě","yú"],meaning:"处卑而不可逾越。逾：越过。"}]}),t[2]||(t[2]=r('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>谦卦是<strong>有实而不露</strong>。坤上艮下，山藏于地中：山本是高物，如今伏在地下，其形不显而其质仍在。</p><p>它是六十四卦中<strong>唯一六爻全吉的卦</strong>。其逻辑基础在于——<strong>结构（九三阳爻得位、得正且有应）与天道（天道亏盈而益谦）高度同向</strong>。人在这样一个「结构合乎天道」的位置上，怎么走都不至于失道。</p><p>六爻也是一条自下而上的位次线：</p><ul><li>初六：入世最低处，纯粹之谦</li><li>六二：安顿立身，内心有得</li><li>九三：功业巅峰，谦德支撑</li><li>六四：承上启下，主动感召</li><li>六五：君位之巅，外柔内刚</li><li>上六：退居幕后，志未竟而守本分</li></ul><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p><strong>它把「谦」从品格问题，改成了结构问题与分配问题。</strong></p><p>三个层次：</p><ol><li><strong>结构层</strong>：谦 = 艮之实 + 坤之地。无实则虚伪，无地则埋没——两样缺一不成</li><li><strong>机制层</strong>：亏盈益谦、裒多益寡、称物平施。谦是资源的动态再分配，与天道的自我调节同向</li><li><strong>分寸层</strong>：卑而不逾、贞、不违则。谦是「有分寸的低」，不是无限退让——六五「利用侵伐」、上六「征邑国」都说明谦有骨头</li></ol><p>最容易被忽略的是第 1 层：我们常把谦当成态度，而它首先是<strong>条件</strong>。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li><strong>先自问「我有实吗」</strong>：无实之谦是虚伪，先有可藏之物</li><li><strong>再自问「我的地够吗」</strong>：同一滴墨，落在杯中全黑、落在海里无痕——选错承载的场域，再好的实也无声</li><li><strong>分清「藏」与「鸣」与「㧑」</strong>：该自守时藏（初六）、内有所得时自然流露（六二）、需要感召时主动施展（六四）——但三者都有边界</li><li><strong>该硬的时候硬</strong>：谦不等于退让到底。对反复不肯归顺的人与事，六五的「征不服」是必要的匡正</li><li><strong>接受「志未得」这一种收尾</strong>：有德而无位时，守住本分、管好自己的「邑国」，也是谦的完成式</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>谦卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞关键词</th><th>处境</th><th>核心</th></tr></thead><tbody><tr><td>卦辞</td><td>谦，亨，君子有终</td><td>有实而藏</td><td>唯一六爻全吉</td></tr><tr><td>初六</td><td>谦谦君子，用涉大川</td><td>最低最初</td><td>谦本身就是渡险之法</td></tr><tr><td>六二</td><td>鸣谦，贞吉</td><td>安顿立身</td><td>中心得也——内有得</td></tr><tr><td>九三</td><td>劳谦，有终吉</td><td>功业巅峰</td><td>有实才谈得上藏实</td></tr><tr><td>六四</td><td>无不利，㧑谦</td><td>承上启下</td><td>主动施展，但不违则</td></tr><tr><td>六五</td><td>不富以其邻，利用侵伐</td><td>君位之巅</td><td>外柔内刚，谦有底线</td></tr><tr><td>上六</td><td>鸣谦，征邑国</td><td>退居幕后</td><td>志未得，而守本分</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>谦之二质</strong>——艮之实 + 坤之地，缺一不成：无实则虚伪，无地则埋没</li><li><strong>亏盈益谦是天道机制</strong>——「损有余而补不足」，谦站在这条机制的同侧</li><li><strong>谦是分配，不是姿态</strong>——裒多益寡、称物平施，像天平寻找平衡</li><li><strong>谦有底线</strong>——外柔内刚：六五「征不服」，不是无限退让</li><li><strong>同辞不同境</strong>——六二「中心得」与上六「志未得」，一句「鸣谦」两种人生</li><li><strong>一条贯穿线</strong>——卑而不逾 / 贞 / 不违则：谦始终是「有分寸的低」</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>读谦卦，我改掉了一个默认反应：<strong>把「谦」从态度问题，移到结构问题。</strong></p><p>以前说一个人谦，我想到的是姿态——低头、少说、不抢。谦卦不是这样。它说谦是<strong>两个条件同时成立</strong>：艮之实（有山的实质、边界与定力）、坤之地（找对能承载的场域）。「若无实则为虚伪，若无地则为埋没」——这句话把我钉住了。我见过不少把自己放得很低的人，其中有些令人敬重，有些毫无声响，差别原来不低在「低」的程度，而在<strong>有没有实、有没有地</strong>。姿态是可以表演的，结构和场域不行。</p><p>第二处是<strong>墨滴模型</strong>。同一滴墨，落在一杯清水里是「全黑」，落在一海里是「无痕」——同样的「山」，因为「地」不同而结果截然相反。我以前常把「不被看见」归因为自己不够好，这个模型给了另一个解释：也许是地选错了。这是我在这一卦里收到的最实用的一条——<strong>先看容量，再谈锋芒</strong>。</p><p>第三处，是象传那八个字给我的震动：<strong>裒多益寡，称物平施</strong>。原来「谦」不是低调做人，而是<strong>资源再分配的动态过程</strong>，像天平寻找平衡。这彻底改了我对这个字的感觉：它不从「我该多卑微」出发，而从「这一份该放到哪里」出发。</p><p>第四处是**「谦有底线」这件事**。六五「利用侵伐」、上六「利用行师」——我之前读谦卦时，以为它是全卦最软的一卦，结果它写得最硬的地方正是这里：谦是外柔内刚。而对反复不肯归顺的人与事，<strong>匡正本身就是谦的一部分</strong>，不是它的反面。</p><p>最后一层是<strong>六二与上六那一组对照</strong>：同样的「鸣谦」，一个是「中心得也」，一个是「志未得也」。同一句话、同一份德，落在不同的位上，心境全然不同。有德而无位时，能守住本分、管好自己的「邑国」，也是谦的一种完成式。这让我对「未被看见」这件事，少了很多焦躁。</p><blockquote><p>谦不是把自己变小，是把该放的东西放到该放的地方；有分寸的低，才是真正的低。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：乾（第一卦）、大有（第十四卦）、豫（第十六卦）、剥（第二十三卦）</li><li>谦与大有（序卦）：序卦「有大者不可以盈，故受之以谦」——有所丰盛之后最需要的正是谦，故谦接大有。</li><li>谦与豫（序卦）：序卦「有大而能谦必豫，故受之以豫」——谦到极处自然和豫，故豫承谦。</li><li>谦与乾（附辨）：乾初九「潜龙勿用」是<strong>因时未到</strong>的被动之隐；谦是<strong>因实已具</strong>而主动选择蛰伏——详见本页「附辨」。</li><li>谦与剥：谦卦「裒多益寡」是主动的向下输送；剥卦「厚下安宅」是被动的向下加固。一为分配，一为自保，都在讲「上者向下」这件事。</li></ul>',28))])}}});export{c as __pageData,y as default};
